ALTER TABLE "generated_files" DROP CONSTRAINT "generated_files_media_type_check", ADD CONSTRAINT "generated_files_media_type_check" CHECK (media_type IN ('image/png', 'image/jpeg', 'image/svg+xml', 'text/csv', 'text/plain', 'text/markdown', 'application/json', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'application/pdf'));